script:
# Filter PAF by query coverage and MAPQ
awk '
    BEGIN {
        printf "sequence_id\tquery_coverage\tidentity\n";
    }
    {
        query_len = $2;
        query_start = $3;
        query_end = $4;
        target = $6;
        matching_bases = $10;
        total_bases = $11;

        if (target == "*") {
            next;
        }

        aligned_len = query_end - query_start;
        query_coverage = aligned_len / query_len;
        identity = matching_bases / total_bases;

        if (query_coverage >= 0.3 && identity >= 0.4) {
            printf "%s\t%.4f\t%.4f\n", $1, query_coverage, identity;
        }
    }
' ERZ101.paf > ERZ101_human_mapped.tsv

# Remove TSV file if it only contains the header (no contaminated contigs found)
if [ $(wc -l < ERZ101_human_mapped.tsv) -le 1 ]; then
    rm ERZ101_human_mapped.tsv
    touch ERZ101_human.txt
else
    # Extract just the sequence IDs from failed sequences
    awk '{print $1}' ERZ101_human_mapped.tsv > ERZ101_human.txt
    gzip ERZ101_human_mapped.tsv
fi

cat <<-END_VERSIONS > versions.yml
"EBIMETAGENOMICS:ASSEMBLY_ANALYSIS_PIPELINE:ASSEMBLY_QC:ASSEMBLY_DECONTAMINATION:HUMAN_DECONTAMINATE_CONTIGS:FILTERPAF":
    gawk: $(echo $(gawk --version 2>&1) | sed 's/^.*GNU Awk //; s/, .*$//')
END_VERSIONS

